    GetMetricDataResponse.add_member(:metric_results, Smithy::Schema::Shapes::ShapeRef.new(shape: HistoricalMetricResults, location_name: 'MetricResults', traits: {"smithy.api#documentation" => "<p>Information about the historical metrics.</p>\n         <p>If no grouping is specified, a summary of metric data is returned.</p>"}))
