    StartChatContactRequest.add_member(:contact_flow_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ContactFlowId, location_name: 'ContactFlowId', traits: {"smithy.api#documentation" => "<p>The identifier of the flow for initiating the chat.\n   To\n   see the ContactFlowId in the Amazon Connect admin website, on the navigation menu go to <b>Routing</b>, <b>Flows</b>. Choose the flow. On the flow page,\n   under the name of the flow, choose <b>Show additional flow\n    information</b>. The ContactFlowId is the last part of the ARN, shown here in bold: </p>\n         <p>arn:aws:connect:us-west-2:xxxxxxxxxxxx:instance/xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx/contact-flow/<b>846ec553-a005-41c0-8341-xxxxxxxxxxxx</b>\n         </p>", "smithy.api#required" => {}}))
