    StartEmailContactRequest.add_member(:references, Smithy::Schema::Shapes::ShapeRef.new(shape: ContactReferences, location_name: 'References', traits: {"smithy.api#documentation" => "<p>A formatted URL that is shown to an agent in the Contact Control Panel (CCP). Emails can\n   have the following reference types at the time of creation: <code>URL</code> |\n    <code>NUMBER</code> | <code>STRING</code> | <code>DATE</code>. <code>EMAIL</code> |\n    <code>EMAIL_MESSAGE</code> |<code>ATTACHMENT</code> are not a supported reference type during\n   email creation.</p>"}))
