    StartOutboundChatContactRequest.add_member(:contact_flow_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ContactFlowId, location_name: 'ContactFlowId', traits: {"smithy.api#documentation" => "<p>The identifier of the flow for the call. To see the ContactFlowId in the Amazon Connect\n   console user interface, on the navigation menu go to <b>Routing, Contact\n    Flows</b>. Choose the flow. On the flow page, under the name of the flow, choose\n    <b>Show additional flow information</b>. The ContactFlowId is the last\n   part of the ARN, shown here in bold:</p>\n         <ul>\n            <li>\n               <p>arn:aws:connect:us-west-2:xxxxxxxxxxxx:instance/xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx/contact-flow/<b>123ec456-a007-89c0-1234-xxxxxxxxxxxx</b>\n               </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    StartOutboundChatContactRequest.add_member(:chat_duration_in_minutes, Smithy::Schema::Shapes::ShapeRef.new(shape: ChatDurationInMinutes, location_name: 'ChatDurationInMinutes', traits: {"smithy.api#documentation" => "<p>The total duration of the newly started chat session. If not specified, the chat session\n   duration defaults to 25 hour. The minimum configurable time is 60 minutes. The maximum\n   configurable time is 10,080 minutes (7 days).</p>"}))
